-- Exemplos resolvidos (08/10/2026): Interceptação, Prisão Temporária e Delegado. Entram em revisão (under_review). Rode no SQL Editor do Supabase.
begin;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar a Lei de Interceptação", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["Há ordem judicial, em segredo de justiça?", "Há indícios razoáveis e nenhum outro meio de prova?", "A medida está dentro do prazo e foi renovada?", "O que fazer com o que foi gravado? (art. 9º e crimes dos arts. 10 e 10-A)"]}], "cases": [{"id": "int-1", "title": "Interceptar para investigar crime punido só com detenção", "scenario": "A polícia suspeita que um vizinho cometeu um crime punido apenas com detenção e pede ao juiz a interceptação do telefone dele. Existem outras formas simples de provar o fato, como testemunhas.", "question": "O juiz pode autorizar a interceptação?", "steps": ["O art. 1º exige ordem do juiz competente, em segredo de justiça.", "O art. 2º veda a interceptação quando não há indícios razoáveis, quando a prova pode ser feita por outros meios disponíveis e quando o fato investigado é punido, no máximo, com detenção.", "Aqui o crime é punido com detenção e há outros meios de prova: duas vedações do art. 2º se encontram."], "conclusion": "Não. A interceptação é medida excepcional; neste caso a lei a proíbe.", "variation": {"scenario": "E se o crime fosse punido com reclusão, houvesse indícios razoáveis e a prova não pudesse ser feita por nenhum outro meio?", "answer": "Aí as vedações do art. 2º deixam de existir e o juiz pode autorizar, desde que o pedido demonstre a necessidade e a decisão seja fundamentada."}, "pitfall": "Achar que basta a polícia pedir. A interceptação só é autorizada quando os requisitos do art. 2º estão atendidos.", "articles": ["Art. 1", "Art. 2"]}, {"id": "int-2", "title": "Quinze dias, renovável: a escuta não pode virar eterna", "scenario": "O juiz autorizou a interceptação do telefone de um investigado. Depois de 40 dias, o delegado continua ouvindo as ligações sem pedir nada ao juiz.", "question": "O delegado pode continuar a interceptação?", "steps": ["O art. 5º diz que a decisão que autoriza a interceptação deve ser fundamentada e o prazo é de 15 dias, renovável por igual tempo uma vez comprovada a indispensabilidade do meio de prova.", "Quem decide sobre o pedido é o juiz, em até 24 horas (art. 4º), e quem executa é a autoridade policial, que dá ciência ao Ministério Público (art. 6º).", "Passados os 15 dias sem renovação, a autorização terminou: o prazo é do juiz, e não do delegado."], "conclusion": "Não. Sem nova decisão judicial depois do prazo, o delegado não pode continuar. É preciso pedir a renovação e demonstrar que a medida continua indispensável.", "variation": {"scenario": "E se o delegado pedisse a renovação no 14º dia e o juiz a concedesse por decisão fundamentada?", "answer": "Está correto: a lei permite a renovação, desde que fundamentada e com a indispensabilidade comprovada."}, "pitfall": "Entender que, uma vez autorizada, a interceptação vale até o fim da investigação. O prazo é de 15 dias por decisão.", "articles": ["Art. 4", "Art. 5", "Art. 6"]}, {"id": "int-3", "title": "Gravar a própria conversa e instalar escuta na sala", "scenario": "Ana grava, pelo celular, a reunião em que o chefe a ameaça. Em outro caso, Rui instala um microfone escondido na sala de reuniões da empresa para ouvir os sócios, sem autorização de ninguém e sem ordem judicial.", "question": "Ana e Rui cometem crime?", "steps": ["O art. 10-A pune a captação ambiental feita sem autorização judicial, quando esta for exigida, com reclusão de 2 a 4 anos e multa.", "O § 1º do art. 10-A diz que não há crime quando a captação é feita por um dos interlocutores. Ana participa da conversa.", "Rui não participa da conversa e age sem ordem. O art. 10 também pune quem promove escuta ambiental sem autorização judicial, com a mesma pena."], "conclusion": "Ana não comete crime. Rui responde pelo crime de captação ou escuta ambiental sem autorização (reclusão de 2 a 4 anos e multa).", "variation": {"scenario": "E se Rui fosse um dos sócios e gravasse a própria reunião de que participa?", "answer": "Sendo interlocutor, ele se enquadra na exceção do § 1º do art. 10-A e não comete esse crime."}, "pitfall": "Concluir que toda gravação sem ordem é crime. A lei trata de modo diferente quem grava a conversa de que participa e o terceiro que escuta às escondidas.", "articles": ["Art. 10", "Art. 10-A"]}]}$json$::jsonb,
  $json$[{"title": "Lei 9.296/1996 — texto oficial (arts. 1º a 10)", "url": "https://www.planalto.gov.br/ccivil_03/leis/l9296.htm", "checked_at": "2026-10-08T02:52:28Z"}]$json$::jsonb,
  '2026-10-08T02:52:28Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-interceptacao-revisao'
on conflict (material_slug, version) do nothing;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar a Prisão Temporária", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["Quem pediu? (polícia ou MP, nunca o juiz de ofício)", "O crime está no rol do art. 1º, III?", "Qual é o prazo? (5+5 ou 30+30)", "O mandado traz o período e o dia da soltura?"]}], "cases": [{"id": "temp-1", "title": "Cinco dias ou trinta: o prazo da temporária", "scenario": "Dois investigados são presos temporariamente: Mário, por um roubo, e Nelson, por crime hediondo. O delegado quer saber até quando cada um pode ficar preso.", "question": "Qual é o prazo de cada prisão temporária?", "steps": ["O art. 2º da Lei 7.960 fixa o prazo de 5 dias, prorrogável por igual período em caso de extrema e comprovada necessidade.", "Para os crimes hediondos e equiparados, o art. 2º, § 4º, da Lei 8.072/1990 prevê prazo maior: 30 dias, prorrogável por igual período.", "Mário se enquadra na regra geral; Nelson, na regra especial dos hediondos."], "conclusion": "Mário: 5 dias, prorrogáveis por mais 5. Nelson: 30 dias, prorrogáveis por mais 30.", "variation": {"scenario": "E se Mário fosse suspeito de um crime hediondo?", "answer": "Aplica-se o prazo de 30 + 30 dias, porque o que vale é o tipo de crime."}, "pitfall": "Decorar um prazo só. A Lei 7.960 traz 5+5; os hediondos têm prazo próprio, de 30+30.", "articles": ["Art. 2"]}, {"id": "temp-2", "title": "O texto de 1989 cita artigos que já não existem", "scenario": "O delegado representa pela prisão temporária de um suspeito de estupro e de outro suspeito de tráfico de drogas. O advogado de defesa diz que a lei cita o art. 214 do Código Penal e a Lei 6.368/1976, que foram revogados, e que por isso não cabe a medida.", "question": "A prisão temporária pode ser decretada nesses casos?", "steps": ["O rol do art. 1º, III, cita crimes por número de artigo e por lei da época de 1989. O texto nunca foi atualizado.", "A reforma de 2009 uniu os antigos crimes no estupro do art. 213 do CP, e a antiga lei de drogas foi substituída pela Lei 11.343/2006.", "Por isso, o rol é lido como referência aos crimes correspondentes na legislação atual (estupro do art. 213 do CP e tráfico do art. 33 da Lei 11.343). O texto literal do art. 1º continua sem atualização."], "conclusion": "Em tese, cabe: o rol é lido como referência aos crimes atuais correspondentes. A defesa tem razão sobre o texto desatualizado, mas isso não elimina a medida; o juiz ainda avalia a necessidade e a fundamentação.", "variation": {"scenario": "E se o crime investigado não constasse do rol do inciso III, mas fosse imprescindível para a investigação (inciso I)?", "answer": "O inciso I sozinho não costuma bastar; a jurisprudência exige que a medida atenda também às hipóteses do rol. Confira o entendimento atual dos tribunais."}, "pitfall": "Achar que \"artigo revogado\" no texto da lei de 1989 significa que o crime saiu do rol. A leitura é de equivalência, não de exclusão.", "articles": ["Art. 1"]}]}$json$::jsonb,
  $json$[{"title": "Lei 7.960/1989 — texto oficial (arts. 1º e 2º)", "url": "https://www.planalto.gov.br/ccivil_03/leis/l7960.htm", "checked_at": "2026-10-08T02:52:28Z"}]$json$::jsonb,
  '2026-10-08T02:52:28Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-temporaria-revisao'
on conflict (material_slug, version) do nothing;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar a Lei do Delegado", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["Qual a natureza da função do delegado? (art. 2º)", "Quem pode tirar o inquérito dele? (§ 4º)", "Quem pode indiciar? (§ 6º)", "Quem pode ser delegado? (art. 3º)"]}], "cases": [{"id": "del-1", "title": "Quem indicia: delegado, promotor ou juiz?", "scenario": "Ao analisar um inquérito, o promotor escreve que \"determina o indiciamento\" de um investigado. Em outro processo, o juiz determina que o delegado indicie um suspeito.", "question": "Essas ordens estão de acordo com a Lei 12.830?", "steps": ["O art. 2º, § 6º, diz que o indiciamento é privativo do delegado de polícia e dar-se-á por ato fundamentado, mediante análise técnico-jurídica do fato.", "O indiciamento é um ato de convencimento da autoridade policial. Nem o promotor nem o juiz o exercem.", "O MP pode requisitar diligências e oferecer ou não a denúncia, e o juiz controla a legalidade, mas nenhum deles indicia."], "conclusion": "Não. O indiciamento é privativo do delegado, por ato fundamentado.", "variation": {"scenario": "E se o delegado deixasse de indiciar quem a prova indicou como autor?", "answer": "O MP pode, ainda assim, denunciar, pois a denúncia não depende do indiciamento. Cada autoridade exerce sua função."}, "pitfall": "Achar que só há denúncia depois do indiciamento. O indiciamento é ato do delegado; a denúncia é do MP.", "articles": ["Art. 2"]}, {"id": "del-2", "title": "Tirar o inquérito do delegado: só por despacho fundamentado", "scenario": "O delegado titular conduz um inquérito sobre um caso sensível. O superior hierárquico, sem dar nenhum motivo, passa o inquérito para outro delegado.", "question": "O superior pode fazer isso?", "steps": ["O art. 2º, § 4º, diz que o inquérito só pode ser avocado ou redistribuído por superior hierárquico mediante despacho fundamentado, por motivo de interesse público ou nas hipóteses de inobservância dos procedimentos previstos em regulamento.", "O § 5º protege o delegado também contra a remoção: só por ato fundamentado.", "A mudança sem motivo declarado contraria o § 4º."], "conclusion": "Não. A avocação ou redistribuição exige despacho fundamentado e uma das duas razões da lei (interesse público ou falha procedimental).", "variation": {"scenario": "E se o superior apontasse, por escrito, que o delegado deixou de seguir o procedimento regulamentar?", "answer": "Há fundamento previsto em lei: a avocação ou a redistribuição pode ocorrer, com despacho fundamentado."}, "pitfall": "Achar que a chefia pode mudar o responsável pelo inquérito livremente. A lei protege a independência do delegado na condução da investigação.", "articles": ["Art. 2"]}]}$json$::jsonb,
  $json$[{"title": "Lei 12.830/2013 — texto oficial (arts. 2º e 3º)", "url": "https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2013/lei/l12830.htm", "checked_at": "2026-10-08T02:52:28Z"}]$json$::jsonb,
  '2026-10-08T02:52:28Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-delegado-revisao'
on conflict (material_slug, version) do nothing;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar a Lei de Abuso de Autoridade", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["Quem é o agente público? (art. 2º)", "Houve finalidade específica? (art. 1º, § 1º)", "A divergência de interpretação é só jurídica? (art. 1º, § 2º)", "Qual o crime e a pena?"]}], "cases": [{"id": "abu-1", "title": "Decisão de que o MP discorda não é abuso", "scenario": "Um juiz solta um investigado com base em sua leitura da lei. O promotor discorda e diz que o juiz cometeu abuso de autoridade.", "question": "Há abuso de autoridade?", "steps": ["O art. 1º, § 1º, exige finalidade específica: prejudicar outrem, beneficiar a si ou a terceiro, ou agir por mero capricho ou satisfação pessoal.", "O § 2º diz que a divergência na interpretação da lei ou na avaliação de fatos e provas não configura abuso de autoridade.", "O juiz apenas interpretou a lei de forma diferente do promotor."], "conclusion": "Não. Sem finalidade específica e com mera divergência de interpretação, não há abuso de autoridade. A discordância se resolve com recurso.", "variation": {"scenario": "E se o juiz tivesse soltado o investigado por ser seu amigo, para beneficiá-lo?", "answer": "Aí há finalidade específica de beneficiar terceiro, e o fato pode ser analisado como abuso de autoridade."}, "pitfall": "Achar que qualquer decisão errada é abuso. É preciso finalidade específica, e a divergência de interpretação não basta.", "articles": ["Art. 1"]}, {"id": "abu-2", "title": "Condução coercitiva sem intimar antes", "scenario": "O delegado manda a polícia buscar uma testemunha em casa para depor, sem que ela tenha sido intimada antes e sem que tenha faltado a nenhuma intimação.", "question": "O delegado cometeu abuso de autoridade?", "steps": ["O art. 10 pune a condução coercitiva ou o constrangimento a comparecer a ato, quando a pessoa não foi previamente intimada a comparecer e não compareceu sem justificativa.", "A pena é detenção de 1 a 4 anos e multa.", "A testemunha não foi intimada: faltou a intimação prévia exigida."], "conclusion": "Em tese, sim. A condução sem intimação prévia se enquadra no art. 10, desde que presente a finalidade específica do art. 1º, § 1º.", "variation": {"scenario": "E se a testemunha tivesse sido intimada duas vezes e faltasse sem justificar?", "answer": "Aí a condução coercitiva é possível, porque ela não compareceu depois de intimada."}, "pitfall": "Achar que a polícia pode conduzir qualquer pessoa a depor. A intimação prévia é regra.", "articles": ["Art. 10"]}, {"id": "abu-3", "title": "Violência institucional: depor de novo e de novo", "scenario": "Uma vítima de crime sexual é ouvida três vezes pelo mesmo fato, em salas diferentes, e é obrigada a descrever tudo de novo diante de várias pessoas, sem necessidade.", "question": "Há crime? E se o agente público ainda a intimidar?", "steps": ["O art. 15-A (incluído pela Lei 14.321/2022) pune quem submete vítima de infração penal ou testemunha de crimes violentos a procedimentos desnecessários, repetitivos ou invasivos, que a levem a reviver a situação de violência ou outras situações de sofrimento ou estigmatização. A pena é detenção de 3 meses a 1 ano e multa.", "Se o agente permite que terceiro intimide a vítima, a pena aumenta em 2/3 (§ 1º).", "Se o próprio agente intimida a vítima, a pena é aplicada em dobro (§ 2º)."], "conclusion": "Sim, em tese há violência institucional (art. 15-A). Se o próprio agente intimida a vítima, a pena é em dobro.", "variation": {"scenario": "E se o procedimento repetido fosse necessário para a investigação e feito do modo menos invasivo possível?", "answer": "O tipo fala em procedimentos desnecessários, repetitivos ou invasivos; a necessidade real do ato e o cuidado com a vítima afastam o crime."}, "pitfall": "Esquecer o art. 15-A, que é o único dispositivo novo (2022) dessa lei, muito cobrado por tratar de revitimização.", "articles": ["Art. 15-A"]}]}$json$::jsonb,
  $json$[{"title": "Lei 13.869/2019 — texto oficial (arts. 1º, 10, 13 e 15-A)", "url": "https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869.htm", "checked_at": "2026-10-08T02:52:28Z"}]$json$::jsonb,
  '2026-10-08T02:52:28Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-abuso-revisao'
on conflict (material_slug, version) do nothing;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar a Lei de Tortura", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["Qual a modalidade? (inciso I, II ou III)", "Quem é o agente e quem é a vítima? (aumentos do § 4º)", "Qual o resultado? (§ 3º)", "Quais as consequências? (§§ 5º, 6º e 7º)"]}], "cases": [{"id": "tor-1", "title": "Bater no preso para confessar", "scenario": "Durante o interrogatório, um policial agride um preso até que ele confesse o furto de que é acusado.", "question": "Que crime o policial comete e como a pena é afetada?", "steps": ["O art. 1º, I, a, pune constranger alguém com emprego de violência ou grave ameaça, causando-lhe sofrimento físico ou mental, com o fim de obter informação, declaração ou confissão. A pena é reclusão de 2 a 8 anos.", "O § 4º, I, aumenta a pena de 1/6 a 1/3 se o crime é cometido por agente público.", "O § 5º prevê a perda do cargo, função ou emprego público e a interdição para o exercício por o dobro do prazo da pena."], "conclusion": "O policial comete tortura (art. 1º, I, a), com a pena aumentada de 1/6 a 1/3 por ser agente público, e perde o cargo.", "variation": {"scenario": "E se, durante o interrogatório, ele só gritasse e xingasse o preso, sem violência e sem grave ameaça?", "answer": "Sem o emprego de violência ou grave ameaça com sofrimento intenso, a conduta pode se enquadrar em outro crime, como o abuso de autoridade."}, "pitfall": "Achar que qualquer excesso do policial é tortura. A lei exige violência ou grave ameaça com intenso sofrimento e a finalidade prevista no inciso.", "articles": ["Art. 1"]}, {"id": "tor-2", "title": "Violência doméstica reiterada: o inciso III de 2026", "scenario": "Durante meses, Clóvis humilha, ameaça e isola a esposa, causando-lhe intenso sofrimento mental, no contexto de violência doméstica e familiar.", "question": "Há tortura?", "steps": ["O art. 1º, III, incluído pela Lei 15.410/2026, pune quem submete mulher, reiteradamente, a intenso sofrimento físico ou mental, no contexto de violência doméstica e familiar.", "Os elementos são: vítima mulher; reiteração; intenso sofrimento; contexto doméstico e familiar.", "Todos estão presentes. A pena é a do caput: reclusão de 2 a 8 anos."], "conclusion": "Sim. Há tortura no contexto de violência doméstica (art. 1º, III), com pena de 2 a 8 anos de reclusão.", "variation": {"scenario": "E se houvesse um único episódio isolado de humilhação?", "answer": "O inciso exige reiteração; um fato isolado não se enquadra no inciso III e pode configurar outros crimes."}, "pitfall": "Esquecer que o inciso III é novo (2026) e que exige reiteração.", "articles": ["Art. 1"]}, {"id": "tor-3", "title": "Tortura com morte: pena, fiança e regime", "scenario": "Em uma delegacia, um agente público tortura um preso e ele morre em consequência das agressões.", "question": "Qual a pena e como o crime é tratado na prisão e no processo?", "steps": ["O § 3º do art. 1º prevê reclusão de 8 a 16 anos se resulta morte (4 a 10 anos se há lesão corporal grave ou gravíssima).", "O § 4º, I, aumenta a pena de 1/6 a 1/3 por ser agente público, e o § 5º determina a perda do cargo.", "O § 6º torna o crime inafiançável e insuscetível de graça ou anistia, e o § 7º manda iniciar o cumprimento em regime fechado."], "conclusion": "Pena de 8 a 16 anos (com o aumento de 1/6 a 1/3), perda do cargo, sem fiança, sem graça e sem anistia, com regime inicial fechado.", "variation": {"scenario": "E se a morte não resultasse, mas só lesão corporal grave?", "answer": "A pena base passa a ser de 4 a 10 anos (§ 3º), mantidos o aumento por ser agente público e as demais consequências."}, "pitfall": "Misturar as penas: 2 a 8 anos (caput), 4 a 10 (lesão grave) e 8 a 16 (morte).", "articles": ["Art. 1"]}]}$json$::jsonb,
  $json$[{"title": "Lei 9.455/1997 — texto oficial (arts. 1º e 2º)", "url": "https://www.planalto.gov.br/ccivil_03/leis/l9455.htm", "checked_at": "2026-10-08T02:52:28Z"}]$json$::jsonb,
  '2026-10-08T02:52:28Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-tortura-revisao'
on conflict (material_slug, version) do nothing;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar a Lei de Crimes Hediondos", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["O crime está no rol do art. 1º (ou é equiparado)?", "Quais vedações do art. 2º? (anistia, graça, indulto, fiança)", "Como fica o regime e a progressão?", "Qual o prazo da temporária e a regra do livramento?"]}], "cases": [{"id": "hed-1", "title": "Furto simples, furto com explosivo e roubo com arma", "scenario": "Três réus foram presos: Lia por furto simples de um celular, Marcos por furto qualificado pelo emprego de explosivo e Nara por roubo com emprego de arma de fogo.", "question": "Quais deles respondem por crime hediondo?", "steps": ["O art. 1º traz a lista dos crimes hediondos. O furto simples não está nela.", "O furto qualificado pelo emprego de explosivo está no inciso IX.", "O roubo circunstanciado (como o praticado com emprego de arma de fogo) está no inciso II."], "conclusion": "Marcos e Nara respondem por crime hediondo; Lia, não. O furto simples não está na lista.", "variation": {"scenario": "E se Lia tivesse furtado com o auxílio de um explosivo?", "answer": "Aí o furto seria o qualificado pelo explosivo, que é hediondo."}, "pitfall": "Achar que todo crime com pena alta é hediondo. Só o é o que está na lista do art. 1º ou é equiparado (tortura, tráfico e terrorismo).", "articles": ["Art. 1"]}, {"id": "hed-2", "title": "Preso por crime hediondo: fiança, liberdade e regime", "scenario": "Um homem é preso em flagrante por crime hediondo e pede liberdade provisória sem fiança, dizendo que a lei dos hediondos proíbe só a fiança.", "question": "O que a lei permite e o que ela veda?", "steps": ["O art. 2º diz que esses crimes são insuscetíveis de anistia, graça e indulto e de fiança.", "A vedação da liberdade provisória foi retirada da lei (Lei 11.464/2007). Ela passa a ser analisada caso a caso, pelos requisitos da prisão preventiva.", "O § 1º manda iniciar o cumprimento da pena em regime fechado, e o § 4º prevê a prisão temporária de 30 dias, prorrogável por igual período."], "conclusion": "O pedido pode ser analisado: a fiança é vedada, mas a liberdade provisória sem fiança não é vedada por lei, e o juiz decide pelos requisitos da prisão preventiva.", "variation": {"scenario": "E se o crime fosse tortura ou tráfico?", "answer": "Valem as mesmas vedações do art. 2º, porque esses crimes são equiparados aos hediondos."}, "pitfall": "Achar que hediondo = sem liberdade. A lei veda a fiança, mas a liberdade provisória é analisada caso a caso.", "articles": ["Art. 2"]}, {"id": "hed-3", "title": "Quanto da pena para progredir e para o livramento condicional?", "scenario": "Dois condenados por crime hediondo, sem morte: Paulo, primário, e Ricardo, reincidente em crime hediondo. Eles querem saber a fração da pena para progredir de regime e o que a lei diz sobre o livramento condicional.", "question": "Como a lei trata cada um?", "steps": ["O § 2º do art. 2º foi revogado pelo Pacote Anticrime (Lei 13.964/2019). A progressão hoje segue o art. 112 da LEP, na redação dada pela Lei 15.358/2026: 70% da pena para o primário em crime hediondo ou equiparado (inciso V) e 80% para o reincidente em crime hediondo ou equiparado (inciso VII).", "O art. 5º da Lei 8.072 acrescentou o inciso V ao art. 83 do CP: o livramento condicional só após o cumprimento de mais de 2/3 da pena, se o apenado não for reincidente específico.", "Ricardo, reincidente em crime hediondo, se enquadra na regra mais dura em ambos os pontos."], "conclusion": "Paulo: 70% para progredir. Ricardo: 80% para progredir. No livramento condicional, é exigido mais de 2/3 da pena e a lei não o concede ao reincidente específico.", "variation": {"scenario": "E se Ricardo, reincidente em hediondo, tivesse causado morte?", "answer": "O art. 112 da LEP traz percentual ainda maior (85%, inciso VIII) e veda o livramento condicional."}, "pitfall": "Usar o § 2º do art. 2º, que foi revogado. A progressão está no art. 112 da LEP. Confira o texto vigente.", "articles": ["Art. 2", "Art. 5"]}]}$json$::jsonb,
